INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_05','V1018','阮明',5,'啊？可是我现在正在教学楼上课，根本走不开，能不能先线上临时冻结一下？我下课马上过去办正式手续。','a ？ kě shì wǒ xiàn zài zhèng zài jiào xué lóu shàng kè ， gēn běn zǒu bù kāi ， néng bù néng xiān xiàn shàng lín shí dòng jié yī xià ？ wǒ xià kè mǎ shàng guò qù bàn zhèng shì shǒu xù 。','Hả? Nhưng giờ em đang học trên giảng đường, không thể rời đi được, anh có thể khóa tạm thời online trước được không ạ? Tan học em chạy qua làm thủ tục chính thức ngay.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_06','V1018','小高',6,'线上只能做临时限制，有效期只有两个小时，时间一到就会自动解除，没办法永久锁定。','xiàn shàng zhǐ néng zuò lín shí xiàn zhì ， yǒu xiào qī zhǐ yǒu liǎng gè xiǎo shí ， shí jiān yī dào jiù huì zì dòng jiě chú ， méi bàn fǎ yǒng jiǔ suǒ dìng 。','Online chỉ có thể giới hạn tạm thời thôi, thời hạn chỉ có hai tiếng, hết giờ là tự động mở lại, không thể khóa vĩnh viễn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_07','V1018','阮明',7,'两小时……应该够我下课赶过去了。麻烦您现在先帮我锁上，别让别人继续登录操作。','liǎng xiǎo shí …… yīng gāi gòu wǒ xià kè gǎn guò qù le 。 má fán nín xiàn zài xiān bāng wǒ suǒ shàng ， bié ràng bié rén jì xù dēng lù cāo zuò 。','Hai tiếng... chắc đủ để em tan học chạy qua kịp. Phiền anh khóa tạm giúp em ngay bây giờ, đừng để người khác tiếp tục đăng nhập thao tác.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_08','V1018','小高',8,'已经帮你临时限制登录了。记住，下课第一时间带学生证过来，重置密码、完善安全验证，不然超时解锁还是有风险。','yǐ jīng bāng nǐ lín shí xiàn zhì dēng lù le 。 jì zhù ， xià kè dì yī shí jiān dài xué shēng zhèng guò lái ， zhòng zhì mì mǎ 、 wán shàn ān quán yàn zhèng ， bù rán chāo shí jiě suǒ hái shì yǒu fēng xiǎn 。','Anh khóa tạm thời đăng nhập cho em rồi đó. Nhớ nhé, tan học là mang thẻ sinh viên qua ngay, đổi mật khẩu, hoàn thiện xác thực bảo mật, không thì hết hạn khóa lại rủi ro đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_09','V1018','阮明',9,'好的好的，我一下课就过去，太感谢您了！','hǎo de hǎo de ， wǒ yī xià kè jiù guò qù ， tài gǎn xiè nín le ！','Dạ vâng, em tan học là qua liền, cảm ơn anh nhiều lắm ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1019','SKC1','社交平台私人照片被恶意转发骚扰，到学校保卫处寻求介入处理',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1019','SIT1019','P1','suon_se','chinh_thuc',NULL,'个人肖像被恶意转发骚扰属于侵权行为，学校保卫处可出具证明协助学生向社交平台申请删除内容、封禁侵权账号。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_01','V1019','阮明',1,'李干事您好，我想来报备一个情况，我最近一直被人网络骚扰。','lǐ gàn shì nín hǎo ， wǒ xiǎng lái bào bèi yí gè qíng kuàng ， wǒ zuì jìn yì zhí bèi rén wǎng luò sāo rǎo 。','Chào anh Lý, em muốn đến báo cáo một việc, gần đây em liên tục bị quấy rối trên mạng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_02','V1019','李干事',2,'你具体说一下是什么情况，怎么被骚扰的？','nǐ jù tǐ shuō yī xià shì shén me qíng kuàng ， zěn me bèi sāo rǎo de ？','Em nói cụ thể xem là chuyện gì, bị quấy rối như thế nào?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_03','V1019','阮明',3,'有人私自保存了我的私人生活照片，转发到社交平台，还一直发私信骚扰我，严重影响我的生活了。','yǒu rén sī zì bǎo cún le wǒ de sī rén shēng huó zhào piàn ， zhuǎn fā dào shè jiāo píng tái ， hái yì zhí fā sī xìn sāo rǎo wǒ ， yán zhòng yǐng xiǎng wǒ de shēng huó le 。','Có người tự ý lưu lại ảnh sinh hoạt riêng tư của em, đăng lên mạng xã hội, còn liên tục nhắn tin riêng quấy rối em, ảnh hưởng nghiêm trọng đến cuộc sống của em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_04','V1019','李干事',4,'所有的骚扰私信、对方转发你照片的页面，全部都截图保存了吗？一定要保留完整记录，这是取证关键。','suǒ yǒu de sāo rǎo sī xìn 、 duì fāng zhuǎn fā nǐ zhào piān de yè miàn ， quán bù dōu jié tú bǎo cún le ma ？ yí dìng yào bǎo liú wán zhěng jì lù ， zhè shì qǔ zhèng guān jiàn 。','Tất cả tin nhắn quấy rối, trang đăng ảnh của em mà đối phương chia sẻ, em đã chụp màn hình lưu lại hết chưa? Nhất định phải giữ đầy đủ bằng chứng, đây là điều then chốt để xác minh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_05','V1019','阮明',5,'都保存好了，一张都没漏。而且对方是校外人员，我完全不知道他是谁，查不到任何身份信息。','dōu bǎo cún hǎo le ， yī zhāng dōu méi lòu 。 ér qiě duì fāng shì xiào wài rén yuán ， wǒ wán quán bù zhī dào tā shì shuí ， chá bú dào rèn hé shēn fèn xìn xī 。','Em lưu hết rồi, không sót cái nào. Với lại đối phương là người ngoài trường, em hoàn toàn không biết là ai, không tra ra được thông tin danh tính gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_06','V1019','李干事',6,'没关系，这个我们可以处理。学校可以出具官方证明，协助你联系社交平台客服，调取对方的注册实名信息。','méi guān xì ， zhè ge wǒ men kě yǐ chǔ lǐ 。 xué xiào kě yǐ chū jù guān fāng zhèng míng ， xié zhù nǐ lián xì shè jiāo píng tái kè fú ， diào qǔ duì fāng de zhù cè shí míng xìn xī 。','Không sao, việc này chúng tôi có thể xử lý. Nhà trường có thể xuất trình giấy xác nhận chính thức, hỗ trợ em liên hệ bộ phận chăm sóc khách hàng của nền tảng mạng xã hội, để lấy thông tin đăng ký thực của đối phương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_07','V1019','阮明',7,'太好了！对方每天都在发消息，我上课、休息都被打扰，真的特别困扰，希望能尽快制止他。','tài hǎo le ！ duì fāng měi tiān dōu zài fā xiāo xī ， wǒ shàng kè 、 xiū xī dōu bèi dǎ rǎo ， zhēn de tè bié kùn rǎo ， xī wàng néng jǐn kuài zhì zhǐ tā 。','Tốt quá ạ! Đối phương ngày nào cũng nhắn tin, em học bài, nghỉ ngơi đều bị quấy rầy, thật sự rất phiền toái, mong sớm ngăn chặn được người đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_08','V1019','李干事',8,'我现在先登记你的个人信息和整件事的经过，今天内就发函给平台，要求对方下架所有你的私人照片，停止骚扰行为。','wǒ xiàn zài xiān dēng jì nǐ de gè rén xìn xī hé zhěng jiàn shì de jīng guò ， jīn tiān nèi jiù fā hán gěi píng tái ， yāo qiú duì fāng xià jià suǒ yǒu nǐ de sī rén zhào piān ， tíng zhǐ sāo rǎo xíng wéi 。','Bây giờ tôi sẽ ghi nhận thông tin cá nhân của em và toàn bộ diễn biến sự việc, trong hôm nay sẽ gửi công văn cho nền tảng, yêu cầu gỡ bỏ toàn bộ ảnh riêng tư của em, chấm dứt hành vi quấy rối.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_09','V1019','阮明',9,'真的太感谢您了，我之前都不知道学校保卫处还能处理这种网络侵权的问题。','zhēn de tài gǎn xiè nín le ， wǒ zhī qián dōu bù zhī dào xué xiào bǎo wèi chù hái néng chǔ lǐ zhè zhǒng wǎng luò qīn quán de wèn tí 。','Em thật sự rất cảm ơn anh, trước giờ em không biết phòng bảo vệ nhà trường còn có thể xử lý cả vấn đề xâm phạm trên mạng như vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_10','V1019','李干事',10,'这是我们的工作范畴，校内师生遭遇网络骚扰、肖像侵权，都可以来报备，我们会全程协助维权。','zhè shì wǒ men de gōng zuò fàn chóu ， xiào nèi shī shēng zāo yù wǎng luò sāo rǎo 、 xiào xiàng qīn quán ， dōu kě yǐ lái bào bèi ， wǒ men huì quán chéng xié zhù wéi quán 。','Đây là phạm vi công việc của chúng tôi, sinh viên và giảng viên trong trường gặp phải quấy rối trên mạng, xâm phạm hình ảnh, đều có thể đến báo cáo, chúng tôi sẽ hỗ trợ bảo vệ quyền lợi trọn vẹn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1020','SKC1','社团活动现场两名同学激烈争吵，上前劝解并通知社团负责人',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1020','SIT1020','P1','twist','tuy_y',NULL,'国内校园社团公共场合发生争吵会影响社团评优，负责人一般会分开双方私下调解，避免当众激化矛盾。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_01','V1020','阮明',1,'小宇！你快过来活动大厅！出事了！','xiǎo yǔ ！ nǐ kuài guò lái huó dòng dà tīng ！ chū shì le ！','Tiểu Vũ ơi! Cậu chạy qua sảnh hoạt động ngay đi! Có chuyện rồi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_02','V1020','小宇',2,'怎么了？我刚在后台整理物资，外面乱糟糟的。','zěn me le ？ wǒ gāng zài hòu tái zhěng lǐ wù zī ， wài miàn luàn zāo zāo de 。','Sao thế? Tớ đang sắp xếp đồ ở hậu trường, ngoài kia loạn hết cả lên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_03','V1020','阮明',3,'策划部两个同学吵得特别凶，声音特别大，谁也不肯让谁，好多新生都围过来看热闹了。','cè huà bù liǎng gè tóng xué chǎo dé tè bié xiōng ， shēng yīn tè bié dà ， shuí yě bù kěn ràng shuí ， hǎo duō xīn shēng dōu wéi guò lái kàn rè nào le 。','Hai bạn bên ban tổ chức cãi nhau dữ lắm, to tiếng kinh khủng, chẳng ai chịu nhường ai, tân sinh viên xúm lại xem đông luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_04','V1020','小宇',4,'天呐，怎么当众吵架啊！这么多新人在，太影响社团形象了。到底因为什么？','tiān nà ， zěn me dāng zhòng chǎo jià a ！ zhè me duō xīn rén zài ， tài yǐng xiǎng shè tuán xíng xiàng le 。 dào dǐ yīn wèi shén me ？','Trời ơi, sao lại cãi nhau trước mặt mọi người thế! Đông tân sinh viên vậy còn gì hình ảnh câu lạc bộ nữa. Rốt cuộc là vì chuyện gì?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_05','V1020','阮明',5,'好像是对这次活动的预算分配意见不一样，两个人越吵越激动，根本劝不住。','hǎo xiàng shì duì zhè cì huó dòng de yù suàn fēn pèi yì jiàn bù yí yàng ， liǎng gè rén yuè chǎo yuè jī dòng ， gēn běn quàn bú zhù 。','Hình như là bất đồng về cách phân bổ ngân sách cho hoạt động lần này, hai người càng cãi càng nóng, khuyên thế nào cũng không được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_06','V1020','小宇',6,'你先试着把他们俩分开，别让他们站在一起对峙，分别拉到两边冷静一下。','nǐ xiān shì zhe bǎ tā men liǎ fēn kāi ， bié ràng tā men zhàn zài yì qǐ duì zhì ， fēn bié lā dào liǎng biān lěng jìng yī xià 。','Cậu thử tách hai người ra trước đi, đừng để họ đứng đối mặt nhau, kéo mỗi người một bên cho bình tĩnh lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_07','V1020','阮明',7,'我试过了！劝了好半天，两个人情绪都特别上头，谁都不愿意听，根本冷静不下来。','wǒ shì guò le ！ quàn le hǎo bàn tiān ， liǎng gè rén qíng xù dōu tè bié shàng tou ， shéi dōu bù yuàn yì tīng ， gēn běn lěng jìng bù xià lái 。','Tớ thử rồi! Khuyên mãi mà cả hai đều đang nóng máu, chẳng ai chịu nghe, không tài nào bình tĩnh lại được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_08','V1020','小宇',8,'行，我马上过去亲自跟他们谈。你先帮忙疏散一下围观的同学，别让大家围着看，场面太尴尬了。','xíng ， wǒ mǎ shàng guò qù qīn zì gēn tā men tán 。 nǐ xiān bāng máng shū sàn yī xià wéi guān de tóng xué ， bié ràng dà jiā wéi zhe kàn ， chǎng miàn tài gān gà le 。','Được rồi, tớ chạy qua nói chuyện trực tiếp với họ ngay. Cậu giúp tớ giải tán đám đông đang xem đi, đừng để mọi người xúm vào xem nữa, ngại lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_09','V1020','阮明',9,'没问题，我来安抚新生，转移一下大家的注意力。','méi wèn tí ， wǒ lái ān fǔ xīn shēng ， zhuǎn yí yī xià dà jiā de zhù yì lì 。','Không vấn đề gì, để tớ trấn an mấy bạn tân sinh viên, hướng sự chú ý của mọi người đi chỗ khác.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_10','V1020','小宇',10,'辛苦你了。社团有矛盾一定要第一时间告诉我，千万别任由矛盾闹大。','xīn kǔ nǐ le 。 shè tuán yǒu máo dùn yí dìng yào dì yī shí jiān gào sù wǒ ， qiān wàn bié rèn yóu máo dùn nào dà 。','Cậu vất vả rồi. Câu lạc bộ có mâu thuẫn gì phải báo tớ ngay, đừng để mâu thuẫn bùng lên to nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1021','SKC1','自习室同学突发癫痫，疏散人群、联系校医、维持现场秩序',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1021','SIT1021','P1','suon_se','ban_chinh_thuc',NULL,'国内校园普及癫痫急救基础常识，发病时禁止强行束缚患者肢体，保持通风、清理周边硬物是基础急救方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_01','V1021','阮明',1,'思琪学姐！快来这边，有个同学突然倒地抽搐了！','sī qí xué jiě ！ kuài lái zhè biān ， yǒu gè tóng xué tū rán dǎo dì chōu chù le ！','Chị Tư Kỳ ơi! Qua đây nhanh, có bạn đột nhiên ngã lăn ra co giật!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_02','V1021','思琪',2,'别慌！大家全部往后退，不要围挤，留出足够的通风空间！','bié huāng ！ dà jiā quán bù wǎng hòu tuì ， bú yào wéi jǐ ， liú chū zú gòu de tōng fēng kōng jiān ！','Đừng hoảng! Mọi người lùi lại hết đi, đừng chen lấn, để chỗ thoáng khí cho bạn ấy!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_03','V1021','阮明',3,'我已经把他身边的桌椅都挪开了，防止他抽搐的时候磕碰受伤，现在要不要立刻打校医电话？','wǒ yǐ jīng bǎ tā shēn biān de zhuō yǐ dōu nuó kāi le ， fáng zhǐ tā chōu chù de shí hòu kē pèng shòu shāng ， xiàn zài yào bù yào lì kè dǎ xiào yī diàn huà ？','Em đã dọn hết bàn ghế xung quanh bạn ấy rồi, để tránh va đập lúc co giật, bây giờ có cần gọi ngay số điện thoại y tế trường không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_04','V1021','思琪',4,'我马上打应急电话！你找件外套或者书本，垫在他头下面，保护好头部。','wǒ mǎ shàng dǎ yìng jí diàn huà ！ nǐ zhǎo jiàn wài tào huò zhě shū běn ， diàn zài tā tóu xià miàn ， bǎo hù hǎo tóu bù 。','Chị gọi cấp cứu ngay đây! Em tìm cái áo khoác hay quyển sách nào đó, kê dưới đầu bạn ấy, để bảo vệ phần đầu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_05','V1021','阮明',5,'好！我马上弄！他现在完全没有意识，一直在不停抽搐。','hǎo ！ wǒ mǎ shàng nòng ！ tā xiàn zài wán quán méi yǒu yì shí ， yì zhí zài bù tíng chōu chù 。','Vâng! Em làm ngay! Bạn ấy giờ hoàn toàn không có ý thức, cứ co giật liên tục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_06','V1021','思琪',6,'记住，千万不要伸手去按住他的手脚，也不要掐人中，强行束缚会造成二次损伤，静静等待校医来就行。','jì zhù ， qiān wàn bú yào shēn shǒu qù àn zhù tā de shǒu jiǎo ， yě bú yào qiā rén zhōng ， qiáng xíng shù fù huì zào chéng èr cì sǔn shāng ， jìng jìng děng dài xiào yī lái jiù xíng 。','Nhớ nhé, tuyệt đối đừng đưa tay giữ chặt tay chân bạn ấy, cũng đừng bấm nhân trung, ép giữ mạnh sẽ gây tổn thương thêm, cứ bình tĩnh chờ y tế trường đến là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_07','V1021','阮明',7,'我知道了！我会看好现场，拦住想上前触碰的同学，维持好秩序。','wǒ zhī dào le ！ wǒ huì kàn hǎo xiàn chǎng ， lán zhù xiǎng shàng qián chù pèng de tóng xué ， wéi chí hǎo zhì xù 。','Em biết rồi ạ! Em sẽ trông chừng hiện trường, ngăn các bạn định chạy lại chạm vào, giữ trật tự cho ổn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_08','V1021','思琪',8,'做得很好。自习室人多，一旦围观慌乱，很容易加重患者情况，还好你处理得很稳妥。','zuò dé hěn hǎo 。 zì xí shì rén duō ， yí dàn wéi guān huāng luàn ， hěn róng yì jiā zhòng huàn zhě qíng kuàng ， hái hǎo nǐ chǔ lǐ dé hěn wěn tuǒ 。','Em làm tốt lắm. Phòng tự học đông người, nếu để mọi người xúm lại hoảng loạn thì rất dễ làm tình trạng bệnh nhân nặng thêm, may mà em xử lý rất ổn thỏa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1022','SKC1','校外租房房东私自换锁不让进门，拨打社区民警协调房屋纠纷',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1022','SIT1022','P1','that_bai_nhe','chinh_thuc',NULL,'租房纠纷属于民事纠纷，民警仅负责现场调解，无权强制破门，双方无法达成一致需走法院民事诉讼。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_01','V1022','阮明',1,'王警官您好，我想求助一下，我租的房子，房东私自把门锁换了，不让我进门。','wáng jǐng guān nín hǎo ， wǒ xiǎng qiú zhù yī xià ， wǒ zū de fáng zi ， fáng dōng sī zì bǎ mén suǒ huàn le ， bù ràng wǒ jìn mén 。','Chào anh công an, em muốn nhờ anh giúp đỡ, nhà em thuê bị chủ nhà tự ý đổi khóa cửa, không cho em vào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_02','V1022','王民警',2,'你先别急，出示一下你的租房合同和身份证件，说清楚房东换锁的具体原因。','nǐ xiān bié jí ， chū shì yī xià nǐ de zū fáng hé tóng hé shēn fèn zhèng jiàn ， shuō qīng chǔ fáng dōng huàn suǒ de jù tǐ yuán yīn 。','Em bình tĩnh đã, cho tôi xem hợp đồng thuê nhà và giấy tờ tùy thân của em, nói rõ lý do chủ nhà đổi khóa là gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_03','V1022','阮明',3,'我房租都是按时全额交的，从来没有拖欠！就是房东突然要涨房租，我没同意，他就直接换锁，不让我进屋了。','wǒ fáng zū dōu shì àn shí quán é jiāo de ， cóng lái méi yǒu tuō qiàn ！ jiù shì fáng dōng tū rán yào zhǎng fáng zū ， wǒ méi tóng yì ， tā jiù zhí jiē huàn suǒ ， bù ràng wǒ jìn wū le 。','Tiền thuê nhà em đều đóng đúng hạn, đủ số, chưa bao giờ nợ cả! Chỉ là chủ nhà đột nhiên đòi tăng tiền thuê, em không đồng ý, thế là ông ấy đổi khóa luôn, không cho em vào nhà nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_04','V1022','王民警',4,'我清楚情况了。房东在租客租期内私自换锁、扣押租客物品，属于违规行为，我现在立刻联系房东过来现场调解。','wǒ qīng chǔ qíng kuàng le 。 fáng dōng zài zū kè zū qī nèi sī zì huàn suǒ 、 kòu yā zū kè wù pǐn ， shǔ yú wéi guī xíng wéi ， wǒ xiàn zài lì kè lián xì fáng dōng guò lái xiàn chǎng tiáo jiě 。','Tôi hiểu tình hình rồi. Chủ nhà tự ý đổi khóa, giữ đồ đạc của người thuê trong thời hạn hợp đồng là hành vi vi phạm, tôi sẽ liên hệ chủ nhà đến hiện trường hòa giải ngay bây giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_05','V1022','阮明',5,'太谢谢您了！我的笔记本电脑、还有留学生居留卡全都在房间里，都是重要物品，而且我今晚没地方住，能不能先让我进屋拿东西？','tài xiè xiè nín le ！ wǒ de bǐ jì běn diàn nǎo 、 hái yǒu liú xué shēng jū liú kǎ quán dōu zài fáng jiān lǐ ， dōu shì zhòng yào wù pǐn ， ér qiě wǒ jīn wǎn méi dì fāng zhù ， néng bù néng xiān ràng wǒ jìn wū ná dōng xī ？','Em cảm ơn anh nhiều lắm! Laptop của em, với cả thẻ cư trú du học sinh đều để trong phòng, toàn đồ quan trọng cả, mà tối nay em cũng không có chỗ ở, anh có thể cho em vào lấy đồ trước được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_06','V1022','王民警',6,'这个不行，民事租房纠纷我们没有强制破门的权限，必须双方当事人到场才能调解。房东现在在外面，大概半小时才能赶过来。','zhè ge bù xíng ， mín shì zū fáng jiū fēn wǒ men méi yǒu qiáng zhì pò mén de quán xiàn ， bì xū shuāng fāng dāng shì rén dào chǎng cái néng tiáo jiě 。 fáng dōng xiàn zài zài wài miàn ， dà gài bàn xiǎo shí cái néng gǎn guò lái 。','Cái này thì không được, tranh chấp thuê nhà dân sự chúng tôi không có quyền phá cửa cưỡng chế, phải có mặt cả hai bên mới hòa giải được. Chủ nhà giờ đang ở ngoài, khoảng nửa tiếng nữa mới tới được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_07','V1022','阮明',7,'半小时啊……那我今晚只能临时住酒店了。关键证件都在屋里，我心里特别不踏实。','bàn xiǎo shí a …… nà wǒ jīn wǎn zhǐ néng lín shí zhù jiǔ diàn le 。 guān jiàn zhèng jiàn dōu zài wū lǐ ， wǒ xīn lǐ tè bié bù tà shí 。','Nửa tiếng à... vậy tối nay em chỉ đành ở tạm khách sạn thôi. Giấy tờ quan trọng đều ở trong phòng, em thấy bất an quá.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_08','V1022','王民警',8,'你放心，我会全程在场等候调解，房东到了之后，我第一时间协调你进屋取出重要证件和随身物品。','nǐ fàng xīn ， wǒ huì quán chéng zài chǎng děng hòu tiáo jiě ， fáng dōng dào le zhī hòu ， wǒ dì yī shí jiān xié tiáo nǐ jìn wū qǔ chū zhòng yào zhèng jiàn hé suí shēn wù pǐn 。','Em yên tâm, tôi sẽ có mặt chờ hòa giải đến cùng, chủ nhà đến rồi tôi sẽ thu xếp để em vào lấy giấy tờ quan trọng và đồ dùng cá nhân ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1023','SKC1','校医院无法处理急症，拨打120同时同步告知国际学院辅导员',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1023','SIT1023','P1','suon_se','ban_chinh_thuc',NULL,'国内高校校医院仅处理轻症，重症统一转送综合医院，留学生可凭留学生医保报销部分急诊费用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_01','V1023','阮明',1,'李导，跟您说个紧急情况，我现在在校医院，身体特别不舒服。','lǐ dǎo ， gēn nín shuō gè jǐn jí qíng kuàng ， wǒ xiàn zài zài xiào yī yuàn ， shēn tǐ tè bié bù shū fú 。','Thầy Lý ơi, em báo thầy một việc gấp, em đang ở bệnh viện trường, người khó chịu lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_02','V1023','李辅导员',2,'怎么了？是哪里不舒服，严重吗？','zěn me le ？ shì nǎ lǐ bù shū fú ， yán zhòng ma ？','Sao vậy? Chỗ nào khó chịu, có nghiêm trọng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_03','V1023','阮明',3,'医生说我是急性肠胃炎，伴随严重脱水，校医院的设备处理不了，已经帮我打了120，要送去综合医院急诊。','yī shēng shuō wǒ shì jí xìng cháng wèi yán ， bàn suí yán zhòng tuō shuǐ ， xiào yī yuàn de shè bèi chǔ lǐ bù liǎo ， yǐ jīng bāng wǒ dǎ le 120， yào sòng qù zōng hé yī yuàn jí zhěn 。','Bác sĩ nói em bị viêm dạ dày ruột cấp, kèm mất nước nặng, thiết bị của bệnh viện trường không xử lý được, đã gọi 120 cho em rồi, phải chuyển đến bệnh viện tổng hợp cấp cứu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_04','V1023','李辅导员',4,'明白了，救护车大概多久能到？你身边现在有人陪着吗？','míng bái le ， jiù hù chē dà gài duō jiǔ néng dào ？ nǐ shēn biān xiàn zài yǒu rén péi zhe ma ？','Thầy hiểu rồi, xe cấp cứu khoảng bao lâu nữa thì đến? Giờ bên cạnh em có ai không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_05','V1023','阮明',5,'大概十分钟就到学校门口，我一个人在这边，居留卡、学生证都带在身上了。','dà gài shí fēn zhōng jiù dào xué xiào mén kǒu ， wǒ yí gè rén zài zhè biān ， jū liú kǎ 、 xué shēng zhèng dōu dài zài shēn shàng le 。','Khoảng mười phút nữa là đến cổng trường, em đang ở đây một mình, thẻ cư trú, thẻ sinh viên em đều mang theo người cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_06','V1023','李辅导员',6,'好，我先登记你的就诊信息，等下会提前跟对接医院说明你的留学生身份，方便你就诊。','hǎo ， wǒ xiān dēng jì nǐ de jiù zhěn xìn xī ， děng xià huì tí qián gēn duì jiē yī yuàn shuō míng nǐ de liú xué shēng shēn fèn ， fāng biàn nǐ jiù zhěn 。','Được, thầy ghi nhận thông tin khám bệnh của em trước, lát nữa thầy sẽ báo trước với bệnh viện tiếp nhận về việc em là du học sinh, để thuận tiện cho em khám bệnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_07','V1023','阮明',7,'辛苦您了！我对这边就医缴费、报销的流程一点都不熟悉，后面还要麻烦您指导我。','xīn kǔ nín le ！ wǒ duì zhè biān jiù yī jiǎo fèi 、 bào xiāo de liú chéng yì diǎn dōu bù shú xī ， hòu miàn hái yào má fán nín zhǐ dǎo wǒ 。','Thầy vất vả rồi ạ! Em chưa quen quy trình đóng viện phí, thanh toán bảo hiểm ở đây chút nào, sau này còn phải nhờ thầy hướng dẫn thêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_08','V1023','李辅导员',8,'别担心，你安心看病就行。我处理完手头的工作就赶去医院，后续留学生医保报销的材料和流程，我稍后全部发给你。','bié dān xīn ， nǐ ān xīn kàn bìng jiù xíng 。 wǒ chǔ lǐ wán shǒu tóu de gōng zuò jiù gǎn qù yī yuàn ， hòu xù liú xué shēng yī bǎo bào xiāo de cái liào hé liú chéng ， wǒ shāo hòu quán bù fā gěi nǐ 。','Đừng lo, em cứ yên tâm khám bệnh. Thầy giải quyết xong việc đang làm là qua bệnh viện ngay, sau đó tài liệu và quy trình thanh toán bảo hiểm y tế du học sinh thầy sẽ gửi hết cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1024','SKC1','异地就医刷卡银行卡被风控冻结，紧急致电银行客服解锁',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1024','SIT1024','P1','twist','chinh_thuc',NULL,'国内银行卡异地大额消费易触发风控冻结，线上临时解锁额度有限，大额资金解冻必须线下网点核验身份。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_01','V1024','阮明',1,'您好，我的银行卡被冻结了！我现在在外地医院看病缴费，刷卡提示账户风控锁定，急需解锁缴费。','nín hǎo ， wǒ de yín háng kǎ bèi dòng jié le ！ wǒ xiàn zài zài wài dì yī yuàn kàn bìng jiǎo fèi ， shuā kǎ tí shì zhàng hù fēng kòng suǒ dìng ， jí xū jiě suǒ jiǎo fèi 。','Alo, thẻ ngân hàng của tôi bị khóa rồi! Tôi đang ở bệnh viện tại một tỉnh khác để đóng viện phí, quẹt thẻ thì báo tài khoản bị kiểm soát rủi ro, tôi cần mở khóa gấp để thanh toán.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_02','V1024','客服',2,'您好，麻烦您提供完整银行卡号、手机预留号，以及您开户证件的后四位，我先核验身份。','nín hǎo ， má fán nín tí gōng wán zhěng yín háng kǎ hào 、 shǒu jī yù liú hào ， yǐ jí nín kāi hù zhèng jiàn de hòu sì wèi ， wǒ xiān hé yàn shēn fèn 。','Chào anh, phiền anh cung cấp đầy đủ số thẻ ngân hàng, số điện thoại đăng ký, và 4 số cuối của giấy tờ mở tài khoản, để tôi xác minh danh tính trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_03','V1024','阮明',3,'卡号6217开头，预留手机号138XXXX2741，证件后四位3152。我现在等着付医药费，真的特别着急。','kǎ hào 6217 kāi tóu ， yù liú shǒu jī hào 138XXXX2741， zhèng jiàn hòu sì wèi 3152。 wǒ xiàn zài děng zhe fù yī yào fèi ， zhēn de tè bié zháo jí 。','Số thẻ bắt đầu bằng 6217, số điện thoại đăng ký là 138XXXX2741, 4 số cuối giấy tờ là 3152. Tôi đang chờ đóng viện phí, thật sự rất gấp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_04','V1024','客服',4,'核验成功。系统检测到您异地大额消费，为了保护账户安全，自动触发了风控冻结。可以线上临时解锁，但有每日支付限额。','hé yàn chéng gōng 。 xì tǒng jiǎn cè dào nín yì dì dà é xiāo fèi ， wèi le bǎo hù zhàng hù ān quán ， zì dòng chù fā le fēng kòng dòng jié 。 kě yǐ xiàn shàng lín shí jiě suǒ ， dàn yǒu měi rì zhī fù xiàn é 。','Xác minh thành công. Hệ thống phát hiện anh có giao dịch lớn ở nơi khác, để bảo vệ an toàn tài khoản nên đã tự động kích hoạt khóa kiểm soát rủi ro. Có thể mở khóa tạm thời online, nhưng sẽ có hạn mức thanh toán trong ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_05','V1024','阮明',5,'临时限额是多少？我这次医药费要两千多。','lín shí xiàn é shì duō shǎo ？ wǒ zhè cì yī yào fèi yào liǎng qiān duō 。','Hạn mức tạm thời là bao nhiêu vậy? Lần này viện phí của tôi hơn hai nghìn tệ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_06','V1024','客服',6,'本次线上临时解锁单日限额只有一千元，不足以支付你的诊疗费用。','běn cì xiàn shàng lín shí jiě suǒ dān rì xiàn é zhǐ yǒu yī qiān yuán ， bù zú yǐ zhī fù nǐ de zhěn liáo fèi yòng 。','Hạn mức mở khóa tạm thời online lần này chỉ có một nghìn tệ mỗi ngày thôi, không đủ để thanh toán chi phí khám chữa bệnh của anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_07','V1024','阮明',7,'那怎么办啊！我人在医院，根本没办法离开，有没有别的办法临时提高一下额度？哪怕暂时解开这次交易也行。','nà zěn me bàn a ！ wǒ rén zài yī yuàn ， gēn běn méi bàn fǎ lí kāi ， yǒu méi yǒu bié de bàn fǎ lín shí tí gāo yī xià é dù ？ nǎ pà zàn shí jiě kāi zhè cì jiāo yì yě xíng 。','Vậy phải làm sao đây! Tôi đang ở bệnh viện, không thể nào rời đi được, có cách nào khác để nâng tạm hạn mức lên không? Hay tạm thời mở riêng cho giao dịch lần này cũng được.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_08','V1024','客服',8,'非常抱歉，银行风控系统规则无法线上更改，大额解冻、解除限额，必须本人携带有效证件到线下网点人工核验办理。','fēi cháng bào qiàn ， yín háng fēng kòng xì tǒng guī zé wú fǎ xiàn shàng gēng gǎi ， dà é jiě dòng 、 jiě chú xiàn é ， bì xū běn rén xié dài yǒu xiào zhèng jiàn dào xiàn xià wǎng diǎn rén gōng hé yàn bàn lǐ 。','Tôi rất xin lỗi, quy định hệ thống kiểm soát rủi ro của ngân hàng không thể thay đổi trực tuyến, việc mở khóa hạn mức lớn bắt buộc phải chính chủ mang giấy tờ hợp lệ đến quầy giao dịch trực tiếp để xác minh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_09','V1024','阮明',9,'这样啊……那我现在根本走不开，只能换别的银行卡缴费了。','zhè yàng a …… nà wǒ xiàn zài gēn běn zǒu bù kāi ， zhǐ néng huàn bié de yín háng kǎ jiǎo fèi le 。','Vậy à... giờ tôi không thể rời đi được, đành phải đổi sang thẻ ngân hàng khác để thanh toán vậy.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1025','SKC1','长途火车大面积晚点错过签证预约，向出入境窗口说明延误申请补受理',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1025','SIT1025','P1','that_bai_nhe','chinh_thuc',NULL,'政务大厅预约号严格分时段管控，交通延误仅可优先预约次日时段，无法直接当日插队办理业务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_01','V1025','阮明',1,'吴主管您好，麻烦您通融一下，我今天预约了签证续签，但是火车大面积晚点，彻底错过预约时间了。','wú zhǔ guǎn nín hǎo ， má fán nín tōng róng yī xià ， wǒ jīn tiān yù yuē le qiān zhèng xù qiān ， dàn shì huǒ chē dà miàn jī wǎn diǎn ， chè dǐ cuò guò yù yuē shí jiān le 。','Chào chú Ngô, phiền chú thông cảm giúp cháu, hôm nay cháu có hẹn gia hạn visa nhưng tàu hỏa bị trễ trên diện rộng nên cháu lỡ mất giờ hẹn rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_02','V1025','吴主管',2,'我先看一下你的延误证明和预约回执，把材料拿出来我核实一下。','wǒ xiān kàn yī xià nǐ de yán wù zhèng míng hé yù yuē huí zhí ， bǎ cái liào ná chū lái wǒ hé shí yī xià 。','Để tôi xem giấy chứng nhận trễ tàu và biên nhận đặt hẹn của em trước, em đưa giấy tờ ra để tôi kiểm tra.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_03','V1025','阮明',3,'这是铁路发的晚点短信，整整延误了三个小时，我赶到大厅的时候已经过号了。','zhè shì tiě lù fā de wǎn diǎn duǎn xìn ， zhěng zhěng yán wù le sān gè xiǎo shí ， wǒ gǎn dào dà tīng de shí hòu yǐ jīng guò hào le 。','Đây là tin nhắn báo trễ tàu của ngành đường sắt gửi ạ, trễ nguyên ba tiếng đồng hồ, lúc cháu chạy đến sảnh thì đã quá số thứ tự mất rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_04','V1025','吴主管',4,'我了解你的情况了。但我们系统的每日预约名额是固定的，当日过号，没有法定特殊事由，不能插队现场办理。','wǒ liǎo jiě nǐ de qíng kuàng le 。 dàn wǒ men xì tǒng de měi rì yù yuē míng é shì gù dìng de ， dāng rì guò hào ， méi yǒu fǎ dìng tè shū shì yóu ， bù néng chā duì xiàn chǎng bàn lǐ 。','Tôi hiểu tình huống của em rồi. Nhưng số lượng suất hẹn mỗi ngày trong hệ thống là cố định, hôm nay đã quá số, nếu không có lý do đặc biệt theo quy định thì không thể chen ngang xử lý tại chỗ được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_05','V1025','阮明',5,'我真的很急！下周我就要出境参加交换项目，要是今天办不了，只能重新预约，最少要等一周，我完全来不及赶流程。','wǒ zhēn de hěn jí ！ xià zhōu wǒ jiù yào chū jìng cān jiā jiāo huàn xiàng mù ， yào shì jīn tiān bàn bù liǎo ， zhǐ néng chóng xīn yù yuē ， zuì shǎo yào děng yī zhōu ， wǒ wán quán lái bù jí gǎn liú chéng 。','Cháu thật sự đang rất gấp ạ! Tuần sau cháu phải xuất cảnh tham gia chương trình trao đổi rồi, nếu hôm nay không xử lý được thì chỉ còn cách đặt lại hẹn, ít nhất phải chờ một tuần, cháu hoàn toàn không kịp làm thủ tục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_06','V1025','吴主管',6,'火车交通延误，不属于政务加急的法定事由，没办法破例当日受理。我最多帮你优先锁定明天最早的预约时段。','huǒ chē jiāo tōng yán wù ， bù shǔ yú zhèng wù jiā jí de fǎ dìng shì yóu ， méi bàn fǎ pò lì dāng rì shòu lǐ 。 wǒ zuì duō bāng nǐ yōu xiān suǒ dìng míng tiān zuì zǎo de yù yuē shí duàn 。','Tàu hỏa bị trễ không thuộc lý do khẩn cấp theo quy định của cơ quan hành chính, nên không thể phá lệ giải quyết ngay trong ngày được. Tôi chỉ có thể giúp em giữ trước khung giờ hẹn sớm nhất của ngày mai thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_07','V1025','阮明',7,'那太好了！明天最早是几点？我明天一定提前很久到，绝对不会再迟到、过号。','nà tài hǎo le ！ míng tiān zuì zǎo shì jǐ diǎn ？ wǒ míng tiān yí dìng tí qián hěn jiǔ dào ， jué duì bú huì zài chí dào 、 guò hào 。','Vậy thì tốt quá ạ! Sớm nhất ngày mai là mấy giờ vậy chú? Mai cháu chắc chắn sẽ đến thật sớm, tuyệt đối không để trễ hay quá số nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_08','V1025','吴主管',8,'早上八点是当日第一号，我给你做优先标记，明天直接凭证件取号办理即可，不用抢号排队。','zǎo shàng bā diǎn shì dāng rì dì yī hào ， wǒ gěi nǐ zuò yōu xiān biāo jì ， míng tiān zhí jiē píng zhèng jiàn qǔ hào bàn lǐ jí kě ， bù yòng qiǎng hào pái duì 。','Tám giờ sáng là số đầu tiên của ngày, tôi sẽ đánh dấu ưu tiên cho em, mai em chỉ cần mang giấy tờ đến lấy số làm thủ tục luôn, không cần chen chúc xếp hàng lấy số nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1101','SVL2','向国际学院提交校外兼职用工备案申请，等待学校审批许可',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1101','SIT1101','P1','twist','ban_chinh_thuc',NULL,'国内高校对留学生校外兼职实行备案制度，企业人事公章是备案审核硬性材料，缺少则无法通过审批。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_01','V1101','阮明',1,'张老师您好，我想提交校外兼职备案表，麻烦您帮忙审核一下吧。','zhāng lǎo shī nín hǎo， wǒ xiǎng tí jiāo xiào wài jiān zhí bèi àn biǎo， má fán nín bāng máng shěn hé yī xià ba。','Chào cô Trương, em muốn nộp mẫu đăng ký làm thêm bên ngoài trường, phiền cô kiểm tra giúp em ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_02','V1101','张老师',2,'先把表格和企业用工证明给我，我看看材料齐不齐。','xiān bǎ biǎo gé hé qǐ yè yòng gōng zhèng míng gěi wǒ， wǒ kàn kàn cái liào qí bù qí。','Em đưa cô mẫu đơn với giấy xác nhận sử dụng lao động của công ty trước, để cô xem hồ sơ đã đủ chưa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_03','V1101','阮明',3,'表格我填好了，可公司那边只盖了业务章，没有人事专用章呢。','biǎo gé wǒ tián hǎo le， kě gōng sī nà biān zhǐ gài le yè wù zhāng， méi yǒu rén shì zhuān yòng zhāng ne。','Mẫu đơn em điền xong rồi, nhưng bên công ty chỉ đóng dấu nghiệp vụ thôi, không có dấu nhân sự riêng đâu ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_04','V1101','张老师',4,'备案必须人事公章，业务章学校这边是不认可的哦。','bèi àn bì xū rén shì gōng zhāng， yè wù zhāng xué xiào zhè biān shì bù rèn kě de ó。','Đăng ký bắt buộc phải có con dấu nhân sự, dấu nghiệp vụ thì nhà trường không công nhận đâu nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_05','V1101','阮明',5,'那我明天再去企业重新盖章，会不会耽误备案审批进度？','nà wǒ míng tiān zài qù qǐ yè chóng xīn gài zhāng， huì bú huì dān wù bèi àn shěn pī jìn dù？','Vậy để mai em quay lại công ty đóng dấu lại, như thế có làm chậm tiến độ xét duyệt đăng ký không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_06','V1101','张老师',6,'没事，你补齐公章后再来，审批一般三个工作日就能出结果。','méi shì， nǐ bǔ qí gōng zhāng hòu zài lái， shěn pī yì bān sān gè gōng zuò rì jiù néng chū jié guǒ。','Không sao đâu, em bổ sung đủ con dấu rồi quay lại là được, thường thì ba ngày làm việc là có kết quả xét duyệt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_07','V1101','阮明',7,'好嘞，辛苦老师啦，我明天一早就去公司补盖章。','hǎo lei， xīn kǔ lǎo shī la， wǒ míng tiān yī zǎo jiù qù gōng sī bǔ gài zhāng。','Dạ được ạ, cảm ơn cô nhiều nha, sáng mai em sẽ qua công ty đóng dấu bổ sung ngay.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1102','SVL2','携带企业实习证明前往出入境大厅办理居留许可实习加注',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1102','SIT1102','P1','suon_se','chinh_thuc',NULL,'外籍学生在中国实习、兼职必须完成居留许可实习加注，无证务工会被处罚甚至影响签证续签。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_01','V1102','阮明',1,'您好，我是外籍留学生，来办理实习加注，这是我的材料。','nín hǎo， wǒ shì wài jí liú xué shēng， lái bàn lǐ shí xí jiā zhù， zhè shì wǒ de cái liào。','Chào anh/chị, tôi là du học sinh nước ngoài, đến làm thủ tục ghi chú thực tập, đây là hồ sơ của tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_02','V1102','小唐',2,'护照、实习协议、学校备案回执都带齐全了吗？','hù zhào、 shí xí xié yì、 xué xiào bèi àn huí zhí dōu dài qí quán le ma？','Anh đã mang đầy đủ hộ chiếu, thỏa thuận thực tập và phiếu xác nhận đăng ký của trường chưa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_03','V1102','阮明',3,'全部都准备好了，我下周就要正式到公司上岗啦。','quán bù dōu zhǔn bèi hǎo le， wǒ xià zhōu jiù yào zhèng shì dào gōng sī shàng gǎng la。','Tôi chuẩn bị đầy đủ hết rồi, tuần sau tôi sẽ chính thức đến công ty nhận việc.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_04','V1102','小唐',4,'材料没问题，采集完人像，五个工作日就能办好加注。','cái liào méi wèn tí， cǎi jí wán rén xiàng， wǔ gè gōng zuò rì jiù néng bàn hǎo jiā zhù。','Hồ sơ không có vấn đề gì, sau khi lấy ảnh khuôn mặt xong, năm ngày làm việc là hoàn tất ghi chú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_05','V1102','阮明',5,'办完加注之后，我就可以合法按照规定时长实习了对吧？','bàn wán jiā zhù zhī hòu， wǒ jiù kě yǐ hé fǎ àn zhào guī dìng shí cháng shí xí le duì ba？','Sau khi làm xong ghi chú, tôi có thể thực tập hợp pháp theo đúng thời hạn quy định phải không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_06','V1102','小唐',6,'没错，没有加注务工属于违规，千万不要提前上岗哦。','méi cuò， méi yǒu jiā zhù wù gōng shǔ yú wéi guī， qiān wàn bú yào tí qián shàng gǎng ó。','Đúng vậy, chưa có ghi chú mà đã đi làm là vi phạm quy định, nhất định đừng nhận việc trước thời hạn nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_07','V1102','阮明',7,'明白，我会等证件办好再去公司报到，麻烦您了。','míng bái， wǒ huì děng zhèng jiàn bàn hǎo zài qù gōng sī bào dào， má fán nín le。','Tôi hiểu rồi, tôi sẽ đợi làm xong giấy tờ rồi mới đến công ty trình diện, cảm ơn anh/chị đã giúp đỡ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1103','SVL2','多份兼职叠加工时超每周20小时，和雇主协商调整排班合规',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1103','SIT1103','P1','suon_se','ban_chinh_thuc',NULL,'国内政策限定留学生在校期间每周校外务工总时长不得超过20小时，所有雇主都需要配合遵守。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_01','V1103','阮明',1,'王店长，我算了下我两份兼职加起来每周工时超20小时，不符合留学生打工规定呢。','wáng diàn zhǎng， wǒ suàn le xià wǒ liǎng fèn jiān zhí jiā qǐ lái měi zhōu gōng shí chāo 20 xiǎo shí， bù fú hé liú xué shēng dǎ gōng guī dìng ne。','Anh Vương ơi, em tính thử rồi, tổng giờ làm của hai công việc bán thời gian của em mỗi tuần vượt quá 20 tiếng, không đúng với quy định làm thêm của du học sinh đâu ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_02','V1103','王店长',2,'还有这种限制吗？我之前不太清楚留学生的用工要求啊。','hái yǒu zhè zhǒng xiàn zhì ma？ wǒ zhī qián bù tài qīng chǔ liú xué shēng de yòng gōng yāo qiú a。','Còn có quy định như vậy nữa à? Trước giờ anh không rõ lắm về yêu cầu tuyển dụng đối với du học sinh.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_03','V1103','阮明',3,'教育局规定外籍学生每周校外工作不能超过二十小时，超时会有风险。','jiào yù jú guī dìng wài jí xué shēng měi zhōu xiào wài gōng zuò bù néng chāo guò èr shí xiǎo shí， chāo shí huì yǒu fēng xiǎn。','Sở giáo dục quy định sinh viên nước ngoài mỗi tuần làm việc bên ngoài trường không được quá hai mươi tiếng, làm quá giờ sẽ có rủi ro đấy ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_04','V1103','王店长',4,'原来是这样，那我把你这边排班每周减少两天，刚好控制工时。','yuán lái shì zhè yàng， nà wǒ bǎ nǐ zhè biān pái bān měi zhōu jiǎn shǎo liǎng tiān， gāng hǎo kòng zhì gōng shí。','Ra là vậy, vậy anh sẽ giảm bớt hai ngày trong lịch làm việc hàng tuần của em, như thế vừa khéo kiểm soát được số giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_05','V1103','阮明',5,'太感谢您理解啦，调整排班之后我两份工作都能安心做。','tài gǎn xiè nín lǐ jiě la， tiáo zhěng pái bān zhī hòu wǒ liǎng fèn gōng zuò dōu néng ān xīn zuò。','Em cảm ơn anh đã thông cảm nhiều lắm ạ, sau khi điều chỉnh lịch làm em có thể yên tâm làm cả hai công việc rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_06','V1103','王店长',6,'没事，合规最重要，下周我重新给你排新班次表。','méi shì， hé guī zuì zhòng yào， xià zhōu wǒ chóng xīn gěi nǐ pái xīn bān cì biǎo。','Không sao đâu, quan trọng nhất là làm đúng quy định, tuần sau anh sẽ sắp lại lịch ca mới cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1104','SVL2','企业要求留学生无加注直接上岗，拒绝并解释合法打工规定',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1104','SIT1104','P1','that_bai_nhe','ban_chinh_thuc',NULL,'企业违规聘用未办理实习加注的外籍学生，市场监管与出入境可对企业处以高额罚款。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_01','V1104','阮明',1,'李姐，我现在还没办好出入境实习加注，暂时没办法上岗的。','lǐ jiě， wǒ xiàn zài hái méi bàn hǎo chū rù jìng shí xí jiā zhù， zàn shí méi bàn fǎ shàng gǎng de。','Chị Lý ơi, hiện giờ em vẫn chưa làm xong ghi chú thực tập ở cơ quan xuất nhập cảnh, nên tạm thời chưa thể nhận việc được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_02','V1104','李姐',2,'先过来上班嘛，加注后面抽空补办就行，不影响日常工作。','xiān guò lái shàng bān ma， jiā zhù hòu miàn chōu kòng bǔ bàn jiù xíng， bù yǐng xiǎng rì cháng gōng zuò。','Cứ đến làm trước đi mà, ghi chú thì sau này tranh thủ bổ sung là được, không ảnh hưởng gì đến công việc hàng ngày đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_03','V1104','阮明',3,'不行的，如果无证务工，不光我会受处罚，公司也要承担责任呢。','bù xíng de， rú guǒ wú zhèng wù gōng， bù guāng wǒ huì shòu chǔ fá， gōng sī yě yào chéng dān zé rèn ne。','Không được đâu ạ, nếu làm việc không có giấy phép thì không chỉ em bị xử phạt, mà công ty cũng phải chịu trách nhiệm đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_04','V1104','李姐',4,'哪有这么严格，之前有外籍学生没办证也干了很久啦。','nǎ yǒu zhè me yán gé， zhī qián yǒu wài jí xué shēng méi bàn zhèng yě gàn le hěn jiǔ la。','Làm gì mà nghiêm ngặt vậy, trước đây có sinh viên nước ngoài không làm giấy tờ mà vẫn làm được lâu đấy thôi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_05','V1104','阮明',5,'出入境会不定期核查企业用工，查到违规会罚款企业，我不能冒险。','chū rù jìng huì bù dìng qī hé chá qǐ yè yòng gōng， chá dào wéi guī huì fá kuǎn qǐ yè， wǒ bù néng mào xiǎn。','Cơ quan xuất nhập cảnh sẽ kiểm tra định kỳ việc sử dụng lao động của doanh nghiệp, nếu phát hiện vi phạm thì công ty sẽ bị phạt, em không thể mạo hiểm được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_06','V1104','李姐',6,'行吧，那等你办好加注再来入职，岗位先给你保留三天。','xíng ba， nà děng nǐ bàn hǎo jiā zhù zài lái rù zhí， gǎng wèi xiān gěi nǐ bǎo liú sān tiān。','Thôi được, vậy đợi em làm xong ghi chú rồi hẵng vào làm, vị trí này chị giữ cho em ba ngày trước đã.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_07','V1104','阮明',7,'麻烦您多等我几天，我会尽快办完证件过来报到。','má fán nín duō děng wǒ jǐ tiān， wǒ huì jǐn kuài bàn wán zhèng jiàn guò lái bào dào。','Phiền chị chờ em thêm mấy ngày, em sẽ làm giấy tờ xong sớm nhất rồi đến trình diện ngay ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1105','SVL2','实习到期超过6个月，咨询出入境续办实习加注流程',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1105','SIT1105','P1','twist','chinh_thuc',NULL,'单次实习加注有效期一般不超过6个月，延长实习必须重新完成学校备案再办理加注续期。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_01','V1105','阮明',1,'您好，我的实习加注快到期，实习时长超过半年，该怎么续办呀？','nín hǎo， wǒ de shí xí jiā zhù kuài dào qī， shí xí shí cháng chāo guò bàn nián， gāi zěn me xù bàn ya？','Chào anh/chị, ghi chú thực tập của tôi sắp hết hạn, thời gian thực tập đã hơn nửa năm rồi, vậy tôi cần làm thủ tục gia hạn như thế nào ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_02','V1105','小周',2,'需要提供企业新出具的延长实习证明，还有学校最新备案回执。','xū yào tí gōng qǐ yè xīn chū jù de yán cháng shí xí zhèng míng， hái yǒu xué xiào zuì xīn bèi àn huí zhí。','Anh cần cung cấp giấy xác nhận gia hạn thực tập mới do công ty cấp, cùng với phiếu xác nhận đăng ký mới nhất của trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_03','V1105','阮明',3,'学校备案回执上周刚过期，是不是要重新去学院申请一份？','xué xiào bèi àn huí zhí shàng zhōu gāng guò qī， shì bú shì yào chóng xīn qù xué yuàn shēn qǐng yī fèn？','Phiếu xác nhận đăng ký của trường mới hết hạn tuần trước, vậy có phải tôi cần quay lại khoa xin cấp lại một bản mới không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_04','V1105','小周',4,'是的，备案材料必须是当月有效，过期回执不能用来续办加注。','shì de， bèi àn cái liào bì xū shì dàng yuè yǒu xiào， guò qī huí zhí bù néng yòng lái xù bàn jiā zhù。','Đúng vậy, hồ sơ đăng ký phải còn hiệu lực trong tháng, phiếu đã hết hạn thì không thể dùng để gia hạn ghi chú được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_05','V1105','阮明',5,'那我今天先回学院重新办备案，明天再来窗口提交材料可以吗？','nà wǒ jīn tiān xiān huí xué yuàn chóng xīn bàn bèi àn， míng tiān zài lái chuāng kǒu tí jiāo cái liào kě yǐ ma？','Vậy hôm nay tôi về khoa làm lại thủ tục đăng ký trước, mai quay lại quầy nộp hồ sơ được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_06','V1105','小周',6,'没问题，材料齐全当天就能受理，记得带白底证件照两张。','méi wèn tí， cái liào qí quán dàng tiān jiù néng shòu lǐ， jì de dài bái dǐ zhèng jiàn zhào liǎng zhāng。','Không vấn đề gì, hồ sơ đầy đủ thì ngay trong ngày là được tiếp nhận, nhớ mang theo hai tấm ảnh thẻ nền trắng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_07','V1105','阮明',7,'好的，我记下来所有要求，不会再漏带材料啦。','hǎo de， wǒ jì xià lái suǒ yǒu yāo qiú， bú huì zài lòu dài cái liào la。','Vâng, tôi sẽ ghi lại đầy đủ các yêu cầu, sẽ không quên mang thiếu giấy tờ nữa đâu.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1106','SVL2','更换兼职单位，重新向学校与出入境提交用工备案材料',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1106','SIT1106','P1','suon_se','ban_chinh_thuc',NULL,'留学生每更换一家兼职/实习单位，都要单独完成学校备案，不能沿用旧单位备案证明。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_01','V1106','阮明',1,'张老师，我换了一份新兼职，需要重新提交备案材料对吧？','zhāng lǎo shī， wǒ huàn le yī fèn xīn jiān zhí， xū yào chóng xīn tí jiāo bèi àn cái liào duì ba？','Cô Trương ơi, em vừa đổi sang một công việc làm thêm mới, cần nộp lại hồ sơ đăng ký đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_02','V1106','张老师',2,'没错，更换用工单位必须重新走备案流程，旧备案自动失效。','méi cuò， gēng huàn yòng gōng dān wèi bì xū chóng xīn zǒu bèi àn liú chéng， jiù bèi àn zì dòng shī xiào。','Đúng vậy, khi đổi nơi làm việc thì bắt buộc phải làm lại quy trình đăng ký, hồ sơ cũ sẽ tự động hết hiệu lực.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_03','V1106','阮明',3,'新公司的用工协议、营业执照复印件我都打印带来了。','xīn gōng sī de yòng gōng xié yì、 yíng yè zhí zhào fù yìn jiàn wǒ dōu dǎ yìn dài lái le。','Thỏa thuận lao động và bản photo giấy phép kinh doanh của công ty mới em đều in ra mang theo hết rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_04','V1106','张老师',4,'材料齐全，我今天录入系统，三天后给你出新备案回执。','cái liào qí quán， wǒ jīn tiān lù rù xì tǒng， sān tiān hòu gěi nǐ chū xīn bèi àn huí zhí。','Hồ sơ đầy đủ rồi, hôm nay cô sẽ nhập vào hệ thống, ba ngày nữa sẽ cấp phiếu xác nhận đăng ký mới cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_05','V1106','阮明',5,'拿到回执我就去出入境更新实习加注，不会耽误上班。','ná dào huí zhí wǒ jiù qù chū rù jìng gēng xīn shí xí jiā zhù， bú huì dān wù shàng bān。','Lấy được phiếu xác nhận rồi em sẽ đi cập nhật ghi chú thực tập ở cơ quan xuất nhập cảnh ngay, sẽ không làm chậm việc đi làm đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_06','V1106','张老师',6,'记得旧兼职单位那边也要办好离职交接，避免两边工时叠加超标。','jì de jiù jiān zhí dān wèi nà biān yě yào bàn hǎo lí zhí jiāo jiē， bì miǎn liǎng biān gōng shí dié jiā chāo biāo。','Nhớ là bên công ty làm thêm cũ cũng phải làm xong thủ tục bàn giao thôi việc, để tránh giờ làm hai bên cộng dồn vượt mức quy định.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_07','V1106','阮明',7,'我已经和上一家店长沟通好离职，您放心吧。','wǒ yǐ jīng hé shàng yī jiā diàn zhǎng gōu tōng hǎo lí zhí， nín fàng xīn ba。','Em đã trao đổi xong với quản lý cửa hàng cũ về việc nghỉ việc rồi ạ, cô cứ yên tâm.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1107','SVL2','参加企业新人岗前安全培训，记录不懂的工作流程提问主管',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1107','SIT1107','P1','suon_se','ban_chinh_thuc',NULL,'国内服务业、制造业上岗前强制安全培训，员工主动提问操作细节会被认为认真负责，雇主很认可。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_01','V1107','阮明',1,'陈主管，刚刚安全培训里的设备操作步骤，我还有两处没听懂呢。','chén zhǔ guǎn， gāng gāng ān quán péi xùn lǐ de shè bèi cāo zuò bù zhòu， wǒ hái yǒu liǎng chù méi tīng dǒng ne。','Anh Trần ơi, phần các bước thao tác thiết bị trong buổi tập huấn an toàn vừa rồi em còn hai chỗ chưa hiểu rõ ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_02','V1107','陈主管',2,'哪一部分不清楚，你直接说，我再给你演示一遍。','nǎ yī bù fèn bù qīng chǔ， nǐ zhí jiē shuō， wǒ zài gěi nǐ yǎn shì yī biàn。','Chỗ nào chưa rõ thì em cứ nói thẳng ra, anh sẽ làm mẫu lại cho em xem một lần nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_03','V1107','阮明',3,'就是清洁机器的断电流程，培训讲得有点快，我没记完整。','jiù shì qīng jié jī qì de duàn diàn liú chéng， péi xùn jiǎng dé yǒu diǎn kuài， wǒ méi jì wán zhěng。','Là quy trình ngắt điện khi vệ sinh máy đó ạ, lúc tập huấn nói hơi nhanh nên em ghi nhớ chưa đầy đủ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_04','V1107','陈主管',4,'我带你到设备旁实操一遍，记住维修清洁必须先断总电源。','wǒ dài nǐ dào shè bèi páng shí cāo yī biàn， jì zhù wéi xiū qīng jié bì xū xiān duàn zǒng diàn yuán。','Anh sẽ dẫn em ra chỗ máy để thực hành lại một lần, nhớ là khi bảo trì vệ sinh thì bắt buộc phải ngắt nguồn điện tổng trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_05','V1107','阮明',5,'原来是这样，还好主动问清楚，不然操作失误会有安全隐患。','yuán lái shì zhè yàng， hái hǎo zhǔ dòng wèn qīng chǔ， bù rán cāo zuò shī wù huì yǒu ān quán yǐn huàn。','Ra là vậy, may mà em chủ động hỏi cho rõ, không thì thao tác sai sẽ có nguy cơ mất an toàn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_06','V1107','陈主管',6,'有不懂的随时来问，千万不要自己随意操作机器哦。','yǒu bù dǒng de suí shí lái wèn， qiān wàn bú yào zì jǐ suí yì cāo zuò jī qì ó。','Có gì không hiểu thì cứ đến hỏi bất cứ lúc nào, tuyệt đối đừng tự ý thao tác máy móc một mình nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_07','V1107','阮明',7,'好的，我会把所有注意事项全部记在笔记本上。','hǎo de， wǒ huì bǎ suǒ yǒu zhù yì shì xiàng quán bù jì zài bǐ jì běn shàng。','Vâng ạ, em sẽ ghi hết tất cả các lưu ý vào sổ tay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1108','SVL2','入职要求提供外国人健康证，咨询办理地点与所需材料',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1108','SIT1108','P1','twist','ban_chinh_thuc',NULL,'外籍从业人员需办理专属外籍健康证明，普通国内健康证无法用于留学生兼职入职。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_01','V1108','阮明',1,'李姐，入职要外国人专用健康证，我不清楚去哪里办理呀？','lǐ jiě， rù zhí yào wài guó rén zhuān yòng jiàn kāng zhèng， wǒ bù qīng chǔ qù nǎ lǐ bàn lǐ ya？','Chị Lý ơi, vào làm cần giấy khám sức khỏe dành riêng cho người nước ngoài, em không rõ đi đâu để làm đây ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_02','V1108','李姐',2,'去市国际旅行卫生保健中心，带上护照和一寸照片就行。','qù shì guó jì lǚ xíng wèi shēng bǎo jiàn zhōng xīn， dài shàng hù zhào hé yī cùn zhào piān jiù xíng。','Đến trung tâm kiểm dịch y tế quốc tế của thành phố, mang theo hộ chiếu với ảnh 1 inch là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_03','V1108','阮明',3,'我今天只有护照，照片落在宿舍，明天过去办理来得及吗？','wǒ jīn tiān zhǐ yǒu hù zhào， zhào piān luò zài sù shè， míng tiān guò qù bàn lǐ lái de jí ma？','Hôm nay em chỉ có hộ chiếu thôi, ảnh để quên ở ký túc xá rồi, mai qua làm có kịp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_04','V1108','李姐',4,'可以，体检当天就能拿临时回执，正式证件三天后领取。','kě yǐ， tǐ jiǎn dàng tiān jiù néng ná lín shí huí zhí， zhèng shì zhèng jiàn sān tiān hòu lǐng qǔ。','Được, hôm khám xong là lấy được biên nhận tạm ngay, còn giấy chính thức thì ba ngày sau lấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_05','V1108','阮明',5,'体检需要空腹吗？我怕早上吃了东西白跑一趟。','tǐ jiǎn xū yào kōng fù ma？ wǒ pà zǎo shàng chī le dōng xī bái pǎo yī tàng。','Khám có cần nhịn ăn không ạ? Em sợ sáng mà ăn gì vào thì lại phải đi lại lần nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_06','V1108','李姐',6,'早上空腹抽血，你明天早点过去，人会少很多。','zǎo shàng kōng fù chōu xuè， nǐ míng tiān zǎo diǎn guò qù， rén huì shǎo hěn duō。','Sáng nhịn ăn để lấy máu, em đi sớm một chút vào ngày mai, người sẽ vắng hơn nhiều đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_07','V1108','阮明',7,'多谢提醒，我明天一早空腹过去体检。','duō xiè tí xǐng， wǒ míng tiān yī zǎo kōng fù guò qù tǐ jiǎn。','Cảm ơn chị nhắc nhé, mai em sẽ nhịn ăn đi khám sớm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1109','SVL2','询问实习/兼职是否提供工作餐、交通补贴、全勤奖励',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1109','SIT1109','P1','suon_se','tuy_y',NULL,'餐饮、零售类兼职普遍设有员工餐、交通补贴、全勤奖，面试入职主动询问福利属于正常沟通。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_01','V1109','阮明',1,'店长，我想问下咱们兼职有没有工作餐和交通补贴呀？','diàn zhǎng， wǒ xiǎng wèn xià zán men jiān zhí yǒu méi yǒu gōng zuò cān hé jiāo tōng bǔ tiē ya？','Quản lý ơi, em muốn hỏi làm bán thời gian ở đây có cơm nhân viên với trợ cấp đi lại không ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_02','V1109','王店长',2,'工作日值班提供免费员工餐，交通补贴每月五十块呢。','gōng zuò rì zhí bān tí gōng miǎn fèi yuán gōng cān， jiāo tōng bǔ tiē měi yuè wǔ shí kuài ne。','Ngày làm trực thì có cơm miễn phí cho nhân viên, trợ cấp đi lại mỗi tháng năm chục nghìn nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_03','V1109','阮明',3,'那全勤奖励是什么标准，每月不迟到就能拿到吗？','nà quán qín jiǎng lì shì shén me biāo zhǔn， měi yuè bù chí dào jiù néng ná dào ma？','Vậy thưởng chuyên cần tính theo tiêu chuẩn nào, tháng không đi trễ là được nhận luôn hả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_04','V1109','王店长',4,'当月无迟到早退、不临时请假，月底多两百元全勤奖。','dàng yuè wú chí dào zǎo tuì、 bù lín shí qǐng jià， yuè dǐ duō liǎng bǎi yuán quán qín jiǎng。','Tháng đó không đi trễ về sớm, không xin nghỉ đột xuất, cuối tháng được thêm hai trăm tệ thưởng chuyên cần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_05','V1109','阮明',5,'福利还挺不错的，我一定会尽量全勤上班。','fú lì hái tǐng bù cuò de， wǒ yí dìng huì jǐn liàng quán qín shàng bān。','Phúc lợi cũng khá ổn đó chứ, em nhất định sẽ cố gắng đi làm đều đặn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_06','V1109','王店长',6,'好好干，后续表现好还能给你调整排班和时薪。','hǎo hǎo gàn， hòu xù biǎo xiàn hǎo hái néng gěi nǐ tiáo zhěng pái bān hé shí xīn。','Cố gắng làm tốt vào, sau này làm tốt còn được điều chỉnh ca làm với lương giờ nữa đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_07','V1109','阮明',7,'好嘞，麻烦店长啦！','hǎo lei， má fán diàn zhǎng la！','Dạ được, phiền quản lý nhiều nha!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1110','SVL2','学习公司考勤打卡系统，忘记打卡找人事补录考勤记录',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1110','SIT1110','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内企业考勤补卡普遍需要主管签字佐证，且每月有固定补卡次数上限，超出会扣除全勤奖金。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_01','V1110','阮明',1,'小吴，我今早上班忘记打卡，能不能帮忙补录一下考勤？','xiǎo wú， wǒ jīn zǎo shàng bān wàng jì dǎ kǎ， néng bù néng bāng máng bǔ lù yī xià kǎo qín？','Tiểu Ngô ơi, sáng nay em đi làm quên chấm công, giúp em bổ sung lại được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_02','V1110','小吴',2,'补打卡需要提交书面说明，还要你的当班主管签字确认。','bǔ dǎ kǎ xū yào tí jiāo shū miàn shuō míng， hái yào nǐ dí dàng bān zhǔ guǎn qiān zì què rèn。','Bổ sung chấm công thì cần nộp bản giải trình bằng văn bản, còn phải có chữ ký xác nhận của quản lý ca em nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_03','V1110','阮明',3,'我现在去找主管签字，签完马上拿过来给你行吗？','wǒ xiàn zài qù zhǎo zhǔ guǎn qiān zì， qiān wán mǎ shàng ná guò lái gěi nǐ xíng ma？','Giờ em đi tìm quản lý ký xong mang qua đưa chị luôn được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_04','V1110','小吴',4,'今天下班前提交都可以，超过当日就没办法补录啦。','jīn tiān xià bān qián tí jiāo dōu kě yǐ， chāo guò dāng rì jiù méi bàn fǎ bǔ lù la。','Hôm nay nộp trước giờ tan làm là được, qua ngày là không thể bổ sung được nữa đâu.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_05','V1110','阮明',5,'原来是有时间限制，还好我及时过来咨询，差点错过。','yuán lái shì yǒu shí jiān xiàn zhì， hái hǎo wǒ jí shí guò lái zī xún， chà diǎn cuò guò。','Ra là có giới hạn thời gian, may mà em đến hỏi kịp lúc, suýt nữa lỡ mất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_06','V1110','小吴',6,'下次记得上下班及时打卡，每月只有三次补卡机会哦。','xià cì jì de shàng xià bān jí shí dǎ kǎ， měi yuè zhǐ yǒu sān cì bǔ kǎ jī huì ó。','Lần sau nhớ chấm công đúng giờ khi đi làm và tan làm nhé, mỗi tháng chỉ có ba lần được bổ sung công thôi đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_07','V1110','阮明',7,'我记住啦，之后一定不会再忘记打卡。','wǒ jì zhù la， zhī hòu yí dìng bú huì zài wàng jì dǎ kǎ。','Em nhớ rồi ạ, sau này nhất định không quên chấm công nữa.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1111','SVL2','企业收取兼职服装押金，协商拒绝并咨询合规收费规则',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1111','SIT1111','P1','suon_se','ban_chinh_thuc',NULL,'中国劳动合同法明确规定，企业不得向劳动者收取押金、保证金，违规收取可向劳动部门投诉。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1111_01','V1111','阮明',1,'店长，入职要交两百元服装押金吗？劳动法不是不允许收押金吗？','diàn zhǎng， rù zhí yào jiāo liǎng bǎi yuán fú zhuāng yā jīn ma？ láo dòng fǎ bú shì bù yǔn xǔ shōu yā jīn ma？','Quản lý ơi, vào làm phải đóng hai trăm tệ tiền cọc đồng phục hả? Luật lao động không phải cấm thu tiền cọc sao ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1111_02','V1111','王店长',2,'很多门店都要收，离职归还服装才会退还押金的。','hěn duō mén diàn dōu yào shōu， lí zhí guī huán fú zhuāng cái huì tuì huán yā jīn de。','Nhiều cửa hàng đều thu vậy đó, khi nghỉ việc trả lại đồng phục thì mới hoàn cọc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1111_03','V1111','阮明',3,'我了解规定，用人单位不能以服装、工具名义收取员工押金呢。','wǒ liǎo jiě guī dìng， yòng rén dān wèi bù néng yǐ fú zhuāng、 gōng jù míng yì shōu qǔ yuán gōng yā jīn ne。','Em có tìm hiểu quy định rồi, đơn vị sử dụng lao động không được lấy danh nghĩa đồng phục, dụng cụ để thu tiền cọc của nhân viên đâu ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1111_04','V1111','王店长',4,'行吧，那我给你登记免费领用，离职完好归还服装就行。','xíng ba， nà wǒ gěi nǐ dēng jì miǎn fèi lǐng yòng， lí zhí wán hǎo guī huán fú zhuāng jiù xíng。','Thôi được rồi, vậy chị ghi nhận là cấp phát miễn phí cho em, khi nghỉ việc trả lại đồng phục còn nguyên là được.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1111_05','V1111','阮明',5,'太感谢您了，我一定会妥善保管工作服，离职完整归还。','tài gǎn xiè nín le， wǒ yí dìng huì tuǒ shàn bǎo guǎn gōng zuò fú， lí zhí wán zhěng guī huán。','Cảm ơn chị nhiều lắm, em nhất định sẽ giữ gìn đồng phục cẩn thận, nghỉ việc sẽ trả lại nguyên vẹn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1111_06','V1111','王店长',6,'没事，合规最重要，之后有任何收费疑问都可以直接问我。','méi shì， hé guī zuì zhòng yào， zhī hòu yǒu rèn hé shōu fèi yí wèn dōu kě yǐ zhí jiē wèn wǒ。','Không sao đâu, đúng quy định là quan trọng nhất, sau này có thắc mắc gì về khoản thu cứ hỏi thẳng chị nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1112','SVL2','工作操作失误损坏客户物品，和主管协商赔偿分摊方案',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1112','SIT1112','P1','twist','ban_chinh_thuc',NULL,'职场新人工作失误造成财物损失，多数中小企业会企业员工分摊赔偿，不会要求员工全额承担。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1112_01','V1112','阮明',1,'陈主管，实在抱歉，我操作失误把客户的水杯摔碎了啊。','chén zhǔ guǎn， shí zài bào qiàn， wǒ cāo zuò shī wù bǎ kè hù de shuǐ bēi shuāi suì le a。','Chú Trần ơi, thật sự xin lỗi, em thao tác sai làm vỡ mất cốc nước của khách rồi ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1112_02','V1112','陈主管',2,'客户刚刚已经投诉过来了，这个杯子原价一百八十元。','kè hù gāng gāng yǐ jīng tóu sù guò lái le， zhè ge bēi zi yuán jià yì bǎi bā shí yuán。','Khách vừa mới khiếu nại lên rồi đó, cái cốc này giá gốc một trăm tám mươi tệ.',NULL) ON CONFLICT DO NOTHING;
